<script setup lang="ts">import{onMounted,ref}from'vue';import{useRoute}from'vue-router';import{api}from'../services/api';const route=useRoute();const detail=ref<any>();onMounted(async()=>detail.value=(await api.get(`/cases/${route.params.id}`)).data)</script>
<template><el-card v-if="detail"><template #header><b>{{detail.case.case_number}} · {{detail.case.title}}</b></template><el-descriptions :column="3" border><el-descriptions-item label="状态">{{detail.case.status}}</el-descriptions-item><el-descriptions-item label="密级">{{detail.case.security_level}}</el-descriptions-item><el-descriptions-item label="版本">v{{detail.case.version}}</el-descriptions-item><el-descriptions-item label="摘要" :span="3">{{detail.case.summary}}</el-descriptions-item></el-descriptions><h3>材料目录</h3><el-table :data="detail.materials"><el-table-column prop="title" label="材料"/><el-table-column prop="responsible" label="责任者"/><el-table-column label="页码"><template #default="s">{{s.row.page_from}}-{{s.row.page_to}}</template></el-table-column></el-table><h3>版本历史</h3><el-timeline><el-timeline-item v-for="v in detail.versions" :key="v.id" :timestamp="v.created_at">v{{v.version}} {{v.reason}}（{{v.diff.join('、')}}）</el-timeline-item></el-timeline></el-card></template>
